'use strict';

function formatAgenda(sections) {
  if (!Array.isArray(sections)) {
    throw new TypeError('sections must be an array');
  }

  return sections.map((section) => {
    if (
      section === null ||
      typeof section !== 'object' ||
      typeof section.heading !== 'string' ||
      section.heading.length === 0 ||
      !Array.isArray(section.bullets) ||
      !section.bullets.every((bullet) => typeof bullet === 'string')
    ) {
      throw new TypeError('invalid section');
    }

    const lines = [`## ${section.heading}`];
    for (const bullet of section.bullets.filter(Boolean)) {
      lines.push(`- ${bullet}`);
    }
    return lines.join('\n');
  }).join('\n\n');
}

module.exports = { formatAgenda };

