'use strict';

const assert = require('node:assert');
const api = require('./solution');

assert.deepStrictEqual(Object.keys(api), ['formatAgenda']);
assert.strictEqual(typeof api.formatAgenda, 'function');
const { formatAgenda } = api;

assert.strictEqual(formatAgenda([]), '');
assert.strictEqual(
  formatAgenda([
    { heading: 'Today', bullets: ['Review', '', 'Deploy'] },
    { heading: 'Later', bullets: [] },
    { heading: 'Notes', bullets: ['Keep order'] }
  ]),
  '## Today\n- Review\n- \n- Deploy\n\n## Later\n\n## Notes\n- Keep order'
);
assert.strictEqual(formatAgenda([{ heading: 'H', bullets: [] }]), '## H');

const sections = [
  { heading: 'Alpha', bullets: ['one', 'two'] },
  { heading: 'Beta', bullets: ['three'] }
];
const snapshot = JSON.parse(JSON.stringify(sections));
assert.strictEqual(formatAgenda(sections), '## Alpha\n- one\n- two\n\n## Beta\n- three');
assert.deepStrictEqual(sections, snapshot);

for (const invalid of [
  null,
  {},
  'x',
  [null],
  [{}],
  [{ heading: '', bullets: [] }],
  [{ heading: 1, bullets: [] }],
  [{ heading: 'Valid', bullets: 'no' }],
  [{ heading: 'Valid', bullets: [1] }],
  [{ heading: 'Valid', bullets: ['ok'] }, { heading: 'Bad', bullets: [null] }]
]) {
  assert.throws(() => formatAgenda(invalid), TypeError);
}

